import traces from "@/lib/data/gap-traces.json";

// ---------------------------------------------------------------------------
// Typed access to the generated search traces.
//
// A cell with no quote used to be a bare 0, and a bare 0 cannot be argued
// with. These records are what the site shows instead: the reach of the search
// that produced it, the provisions that came closest in their own words, and a
// dated reading of why those provisions fall short.
//
// The JSON is generated by scripts/build-gap-traces.mjs and re-derived by
// scripts/check-gap-traces.mjs, so anything read through here has been proven
// to be a faithful slice of the ingested text rather than prose about it.
// ---------------------------------------------------------------------------

/** One provision the search surfaced, with a verbatim window of its text. */
export interface TraceCandidate {
  /** Provision key in the index, e.g. "sch1-4.9". */
  key: string;
  /** Human-readable form, e.g. "Schedule 1, clause 4.9". */
  label: string;
  /** Which search terms this provision matched. */
  matched: string[];
  /** Verbatim slice of the provision, whitespace collapsed. */
  excerpt: string;
  truncatedStart: boolean;
  truncatedEnd: boolean;
  /** True where the author named this provision as a closest match. */
  named: boolean;
}

/**
 * A neighbouring requirement that carries the constraint this cell lacks.
 *
 * The GDPR has no provision requiring data to be stored in the Union, so its
 * data-localization cell is honestly 0 — but Art. 44 permits export "only if"
 * Chapter V's conditions are met, which makes EEA storage the one route that
 * avoids the whole apparatus. Shown as a bare 0 beside California's genuine
 * nil, that reads as "the GDPR does not care where data lives", which is the
 * opposite of the truth. Resolved from the catalog at build time, so the score
 * shown is always the live one.
 */
export interface HandledBy {
  requirementId: string;
  name: string;
  /**
   * "instead-of"         the same ground is genuinely constrained, by another
   *                      route — the 0 understates the position, and only this
   *                      kind is marked beside the score in the comparison.
   * "different-approach" related and NOT equivalent. California's contract
   *                      terms are worth reading next to its nil on data
   *                      location, but they do not limit where data may live.
   */
  kind: "instead-of" | "different-approach";
  /** What is there, in one line. */
  note: string;
  /** This law's score on that requirement — always higher than the cell's own. */
  strictness: number;
  citation: string;
  obligation: string;
  quoted: boolean;
}

export interface GapTrace {
  lawId: string;
  requirementId: string;
  strictness: number;
  sourceType: string;
  obligation: string;
  citation: string;

  // --- mechanical: reproducible from the corpus --------------------------
  /** How many provisions of this instrument were read. */
  provisionsSearched: number;
  termsTried: string[];
  /** Terms that appear nowhere in the instrument — evidence in its own right. */
  termsAbsent: string[];
  candidatesFound: number;
  /** Provisions reached only by a word too general to carry a near-miss. */
  weakOnly: number;
  candidates: TraceCandidate[];

  // --- judgement: authored, dated ----------------------------------------
  nearest: string[];
  noNearest: boolean;
  verdict: string;
  /** What the position amounts to in practice, where that differs from the score. */
  practicalEffect: string | null;
  elsewhere: string | null;
  handledBy: HandledBy[];
  reviewed: string;
  /** Set where the instrument's source cannot support provision-level scoping. */
  degraded: string | null;
}

export const gapTraces = traces as unknown as Record<string, GapTrace>;

export function traceFor(lawId: string, requirementId: string): GapTrace | null {
  return gapTraces[`${lawId}/${requirementId}`] ?? null;
}

/**
 * Every trace behind one requirement across a set of laws.
 *
 * The comparison aggregates a jurisdiction by taking its strictest law per
 * requirement, so a 0 at jurisdiction level means EVERY law there scored 0 and
 * the reader needs every one of those traces, not just one.
 */
export function tracesFor(lawIds: string[], requirementId: string): GapTrace[] {
  return lawIds.map((id) => traceFor(id, requirementId)).filter((t): t is GapTrace => t !== null);
}

/**
 * Does a 0 in this cell understate the position?
 *
 * True where the instrument constrains the same ground through another
 * requirement. The comparison tables use it to mark such a cell, so a score
 * that is legally correct but practically misleading cannot pass as a plain
 * nil.
 */
export function understatedBy(lawIds: string[], requirementId: string): HandledBy[] {
  const seen = new Set<string>();
  const out: HandledBy[] = [];
  for (const t of tracesFor(lawIds, requirementId)) {
    // Only "instead-of". A related row that imposes nothing equivalent belongs
    // inside the trace as further reading, not as a mark beside the score —
    // marking it would say California limits where data may live.
    for (const h of t.handledBy.filter((x) => x.kind === "instead-of")) {
      if (seen.has(h.requirementId)) continue;
      seen.add(h.requirementId);
      out.push(h);
    }
  }
  return out;
}

/** Headline counts, for the provenance page. */
export function traceCoverage() {
  const all = Object.values(gapTraces);
  return {
    cells: all.length,
    provisionReads: all.reduce((n, t) => n + t.provisionsSearched, 0),
    silent: all.filter((t) => t.noNearest).length,
    reviewed: all[0]?.reviewed ?? "",
  };
}
